fn arb_valid_input() -> impl Strategy<Value = Input> {
    (
        "[a-z]{1,20}",
        prop::collection::vec(any::<u8>(), 1..128),
        arb_valid_authorization(),
        prop::collection::vec(any::<u8>(), 0..64),
    )
        .prop_map(|(payload_type, data, auth, aux_data)| Input {
            payload: Payload { payload_type, data },
            auth,
            aux: AuxiliaryData { data: aux_data },
        })
}

fn arb_observable() -> impl Strategy<Value = Observable> {
    (
        prop_oneof![
            Just(TransitionClass::Update),
            Just(TransitionClass::Init),
            Just(TransitionClass::Noop),
        ],
        0u64..=1_000_000u64,
    )
        .prop_map(|(class, gas)| {
            let status = match class {
                TransitionClass::Update | TransitionClass::Init => TransitionStatus::Success,
                _ => TransitionStatus::Rejected,
            };
            Observable {
                transition_class: class,
                outputs: vec![],
                gas_used: gas,
                status,
            }
        })
}

// ---------------------------------------------------------------------------
// Trace construction helpers
// ---------------------------------------------------------------------------

/// Build a valid trace from an initial state and a sequence of inputs.
fn build_trace(initial_state: State, inputs: Vec<Input>, observables: Vec<Observable>) -> Trace {
    let init_commit = commit(&initial_state.canonical);
    let mut entries = Vec::new();
    let mut prev_chain = Hash([0u8; 32]);

    for (i, (input, obs)) in inputs.into_iter().zip(observables.into_iter()).enumerate() {
        let pre_commit = if i == 0 {
            init_commit.clone()
        } else {
            let mut h = [0u8; 32];
            h[0] = i as u8;
            h[1] = (i >> 8) as u8;
            Hash(h)
        };
        let mut post_hash = [0u8; 32];
        post_hash[0] = (i + 1) as u8;
        post_hash[1] = ((i + 1) >> 8) as u8;

        // Compute chain hash deterministically
        let mut chain_data = Vec::new();
        chain_data.extend_from_slice(&prev_chain.0);
        chain_data.extend_from_slice(&pre_commit.0);
        chain_data.extend_from_slice(&post_hash);
        chain_data.extend_from_slice(&(i as u64).to_le_bytes());
        let chain_hash = {
            use sha3::{Digest, Sha3_256};
            let mut hasher = Sha3_256::new();
            hasher.update(&chain_data);
            let result = hasher.finalize();
            let mut bytes = [0u8; 32];
            bytes.copy_from_slice(&result);
            Hash(bytes)
        };

        entries.push(TraceEntry {
            index: i as u64,
            pre_state_commitment: pre_commit,
            input,
            post_state_commitment: Hash(post_hash),
            observable: obs,
            environment: initial_state.environment.clone(),
            chain_hash: chain_hash.clone(),
        });

        prev_chain = chain_hash;
    }

    let final_commitment = if let Some(last) = entries.last() {
        last.chain_hash.clone()
    } else {
        Hash([0u8; 32])
    };

    Trace {
        entries,
        initial_state,
        commitment: final_commitment,
    }
}

/// Build a minimal constraint system for testing.
///
/// Uses `Eq(WitnessRef("x"), WitnessRef("x"))` which compiles to the
/// polynomial identity `x - x = 0` — trivially satisfiable for any trace.
/// This works with both the HashBackend (which doesn't evaluate AIR) and
/// the Plonky3Backend (which requires AIR constraints to hold on every row).
fn test_constraint_system() -> ConstraintSystem {
    let mut cs = ConstraintSystem::new("1.0.0");
    cs.add_witness_variable(vsel_constraints::WitnessVariable {
        name: "x".to_string(),
        kind: vsel_constraints::WitnessVariableKind::Semantic,
        description: "test witness variable".to_string(),
    });
    cs.add_constraint(Constraint {
        id: ConstraintId(0),
        expr: ConstraintExpr::Eq(
            Box::new(ConstraintExpr::WitnessRef("x".to_string())),
            Box::new(ConstraintExpr::WitnessRef("x".to_string())),
        ),
        category: ConstraintCategory::Structural,
        description: "x = x (trivially true)".to_string(),
    });
    cs
}

// ---------------------------------------------------------------------------
// Trace strategies — varying sizes for differential coverage
// ---------------------------------------------------------------------------

/// Strategy for generating a single-entry trace.
fn arb_single_entry_trace() -> impl Strategy<Value = Trace> {
    (arb_valid_state(), arb_valid_input(), arb_observable())
        .prop_map(|(state, input, obs)| build_trace(state, vec![input], vec![obs]))
}

/// Strategy for generating a multi-entry trace (5+ entries).
fn arb_multi_entry_trace() -> impl Strategy<Value = Trace> {
    (arb_valid_state(), 5usize..=8)
        .prop_flat_map(|(state, n)| {
            let inputs = prop::collection::vec(arb_valid_input(), n);
            let observables = prop::collection::vec(arb_observable(), n);
            (Just(state), inputs, observables)
        })
        .prop_map(|(state, inputs, observables)| build_trace(state, inputs, observables))
}

/// Strategy for generating a valid trace with 1-5 entries (general).
fn arb_valid_trace() -> impl Strategy<Value = Trace> {
    (arb_valid_state(), 1usize..=5)
        .prop_flat_map(|(state, n)| {
            let inputs = prop::collection::vec(arb_valid_input(), n);
            let observables = prop::collection::vec(arb_observable(), n);
            (Just(state), inputs, observables)
        })
        .prop_map(|(state, inputs, observables)| build_trace(state, inputs, observables))
}

/// Strategy for generating error traces (Noop transitions → Rejected status).
fn arb_error_trace() -> impl Strategy<Value = Trace> {
    (arb_valid_state(), 1usize..=3)
        .prop_flat_map(|(state, n)| {
            let inputs = prop::collection::vec(arb_valid_input(), n);
            let observables = prop::collection::vec(
                (0u64..=1_000_000u64).prop_map(|gas| Observable {
                    transition_class: TransitionClass::Noop,
                    outputs: vec![],
                    gas_used: gas,
                    status: TransitionStatus::Rejected,
                }),
                n,
            );
            (Just(state), inputs, observables)
        })
        .prop_map(|(state, inputs, observables)| build_trace(state, inputs, observables))
}

// ---------------------------------------------------------------------------
// Helper: compute constraint commitment (same as backend_tests.rs)
// ---------------------------------------------------------------------------

fn compute_constraint_commitment(cs: &ConstraintSystem) -> Hash {
    use sha3::{Digest, Sha3_256};
    let cs_bytes = bincode::serialize(cs).unwrap();
    let mut hasher = Sha3_256::new();
    hasher.update(b"vsel-constraint-system-v1");
    hasher.update(&cs_bytes);
    let hash = hasher.finalize();
    let mut commitment = [0u8; 32];
    commitment.copy_from_slice(&hash);
    Hash(commitment)
}

// ---------------------------------------------------------------------------
// Helper: run differential comparison on a trace
//
// For a given trace and constraint system:
// 1. Both backends produce proofs successfully
// 2. Both proofs pass their respective verification pipelines
// 3. Public inputs derived from the trace are identical (they come from
//    the same trace via PublicInputs::from_trace)
// 4. Witness commitments are semantically equivalent (same witness)
// ---------------------------------------------------------------------------

/// Verify that both backends produce valid proofs for the same trace,
/// and that the public inputs are identical.
fn assert_differential_equivalence(trace: &Trace, cs: &ConstraintSystem) {
    let hash_backend = HashBackend::new();
    let plonky3_backend = Plonky3Backend::new();

    // Both backends operate on the same witness and public inputs.
    let witness = construct_witness(trace);
    let public_inputs = PublicInputs::from_trace(trace);
    let constraint_commitment = compute_constraint_commitment(cs);

    // --- HashBackend prove + verify ---
    let hash_proof = hash_backend
        .prove(&witness, cs, &public_inputs)
        .expect("HashBackend::prove should succeed");

    assert!(
        hash_backend.verify(&hash_proof, &public_inputs, &constraint_commitment),
        "HashBackend proof must pass verification"
    );

    // --- Plonky3Backend prove + verify ---
    let plonky3_proof = plonky3_backend
        .prove(&witness, cs, &public_inputs)
        .expect("Plonky3Backend::prove should succeed");

    assert!(
        plonky3_backend.verify(&plonky3_proof, &public_inputs, &constraint_commitment),
        "Plonky3Backend proof must pass verification"
    );

    // --- Differential: public inputs are identical ---
    // Both backends derive public inputs from the same trace, so they
    // must be identical. This is the core semantic equivalence check.
    let hash_pub = PublicInputs::from_trace(trace);
    let plonky3_pub = PublicInputs::from_trace(trace);

    assert_eq!(
        hash_pub.root_init, plonky3_pub.root_init,
        "root_init must be identical between backends"
    );
    assert_eq!(
        hash_pub.root_final, plonky3_pub.root_final,
        "root_final must be identical between backends"
    );
    assert_eq!(
        hash_pub.observables, plonky3_pub.observables,
        "observables must be identical between backends"
    );
    assert_eq!(
        hash_pub.domain, plonky3_pub.domain,
        "domain must be identical between backends"
    );
    assert_eq!(
        hash_pub.version, plonky3_pub.version,
        "version must be identical between backends"
    );

    // --- Proof bytes differ (different mechanisms) but both are valid ---
    // SHA3-256 commitments vs STARK simulation produce different bytes.
    // This is expected — the key invariant is semantic equivalence of
    // public inputs, not byte-level proof equality.
}

